package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LoginVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property login of smtp outbound config ")
  void test_login_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> LoginVO.tryFrom(null));
    Assertions.assertEquals("one", LoginVO.from("one").getLogin());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LoginVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LoginVO.from("one").toString());
  }
}
